/**
 * The types `data/charts/` exports, in one place — so a neighbouring module finds the shape it
 * needs here instead of declaring its own under a second name.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    WaveAcceleratorSpawnRatesRow, EnemyBalanceMasteryRow
 * depends    —
 * used by    src/data/charts/data, src/data/charts/index, src/mechanics/waves/accelerator-spawn-rate-cap
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */

// from data.ts

